// Filename: uart_regs.h
// Author: FPGA Cores 4 U
// Description: C header of the uart register map (generated by regmap_gen.py): byte offsets, reset values,
//   field shifts and masks.
// Date: 2026-10-20
#ifndef UART_REGS_H
#define UART_REGS_H
#define UART_REGS_ID_OFFSET 0x00u
#define UART_REGS_VERSION_OFFSET 0x04u
#define UART_REGS_DATE_OFFSET 0x08u
#define UART_REGS_ID_VALUE 0x55415254u   /* "UART" */
#define UART_REGS_CTRL_OFFSET 0x10u   /* RW */
#define UART_REGS_CTRL_RESET 0x00000003u
#define UART_REGS_CTRL_TX_EN_SHIFT 0u
#define UART_REGS_CTRL_TX_EN_MASK 0x00000001u
#define UART_REGS_CTRL_RX_EN_SHIFT 1u
#define UART_REGS_CTRL_RX_EN_MASK 0x00000002u
#define UART_REGS_CTRL_PAR_EN_SHIFT 2u
#define UART_REGS_CTRL_PAR_EN_MASK 0x00000004u
#define UART_REGS_CTRL_PAR_ODD_SHIFT 3u
#define UART_REGS_CTRL_PAR_ODD_MASK 0x00000008u
#define UART_REGS_CTRL_STOP2_SHIFT 4u
#define UART_REGS_CTRL_STOP2_MASK 0x00000010u
#define UART_REGS_CTRL_LOOPBACK_SHIFT 5u
#define UART_REGS_CTRL_LOOPBACK_MASK 0x00000020u
#define UART_REGS_CTRL_BITS_SHIFT 6u
#define UART_REGS_CTRL_BITS_MASK 0x000000C0u
#define UART_REGS_FCW_OFFSET 0x14u   /* RW */
#define UART_REGS_STATUS_OFFSET 0x18u   /* CMD */
#define UART_REGS_STATUS_RESET 0x00000000u
#define UART_REGS_STATUS_TX_BUSY_SHIFT 0u
#define UART_REGS_STATUS_TX_BUSY_MASK 0x00000001u
#define UART_REGS_STATUS_RX_BUSY_SHIFT 1u
#define UART_REGS_STATUS_RX_BUSY_MASK 0x00000002u
#define UART_REGS_STATUS_RX_AVAIL_SHIFT 2u
#define UART_REGS_STATUS_RX_AVAIL_MASK 0x00000004u
#define UART_REGS_STATUS_FRAME_ERR_SHIFT 8u
#define UART_REGS_STATUS_FRAME_ERR_MASK 0x00000100u
#define UART_REGS_STATUS_PARITY_ERR_SHIFT 9u
#define UART_REGS_STATUS_PARITY_ERR_MASK 0x00000200u
#define UART_REGS_STATUS_OVERRUN_SHIFT 10u
#define UART_REGS_STATUS_OVERRUN_MASK 0x00000400u
#define UART_REGS_STATUS_RX_LEVEL_SHIFT 16u
#define UART_REGS_STATUS_RX_LEVEL_MASK 0x7FFF0000u
#define UART_REGS_ERR_CNT_OFFSET 0x1Cu   /* RO */
#define UART_REGS_ERR_CNT_RESET 0x00000000u
#endif /* UART_REGS_H */
